def max_turbulence_size(arr):
    n = len(arr)
    best = 1
    for start in range(n):
        for end in range(start, n):
            ok = True
            for i in range(start, end):
                if arr[i] == arr[i + 1]:
                    ok = False
                    break                                                    # equal adjacent elements can never be turbulent
                if i > start:
                    prev_increasing = arr[i] > arr[i - 1]
                    cur_increasing = arr[i + 1] > arr[i]
                    if prev_increasing == cur_increasing:
                        ok = False
                        break                                                # direction must alternate at every step
            if ok:
                best = max(best, end - start + 1)
    return best


