import java.util.*;

public class Main {
    int maxTurbulenceSize(int[] arr) {
        int n = arr.length;
        int best = 1;
        for (int start = 0; start < n; start++) {
            for (int end = start; end < n; end++) {
                boolean ok = true;
                for (int i = start; i < end; i++) {
                    if (arr[i] == arr[i + 1]) { ok = false; break; }               // equal adjacent elements can never be turbulent
                    if (i > start) {
                        boolean prevIncreasing = arr[i] > arr[i - 1];
                        boolean curIncreasing = arr[i + 1] > arr[i];
                        if (prevIncreasing == curIncreasing) { ok = false; break; }  // direction must alternate at every step
                    }
                }
                if (ok) best = Math.max(best, end - start + 1);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxTurbulenceSize(new int[]{9, 4, 2, 10, 7, 8, 8, 1, 9}));
    }
}

